export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";
const BASE_SPHINX_SCORE = 2;
const BONUS_SPHINX_SCORE = 3;
const NO_SPHINX_SCORE = 0;
const BONUS_TYPE_THRESHOLD = 3;

export const scoreArmy = (army: Card[]): number => {
  const monsters = army.map((card) => card.monster);
  if (!monsters.includes(SPHINX)) return NO_SPHINX_SCORE;

  const distinctTypeCount = new Set(monsters).size;
  return distinctTypeCount > BONUS_TYPE_THRESHOLD
    ? BONUS_SPHINX_SCORE
    : BASE_SPHINX_SCORE;
};

export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";
const BASE_SPHINX_SCORE = 2;
const BONUS_SPHINX_SCORE = 3;
const NO_SPHINX_SCORE = 0;
const BONUS_TYPE_THRESHOLD = 3;

export const scoreArmy = (army: Card[]): number => {
  const monsters = army.map((card) => card.monster);
  if (!monsters.includes(SPHINX)) return NO_SPHINX_SCORE;

  const distinctTypeCount = new Set(monsters).size;
  if (distinctTypeCount <= BONUS_TYPE_THRESHOLD) return BASE_SPHINX_SCORE;

  return 2 * (distinctTypeCount - BONUS_TYPE_THRESHOLD) - 1;
};

export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";
const BASE_SPHINX_SCORE = 2;
const BONUS_SPHINX_SCORE = 3;
const NO_SPHINX_SCORE = 0;
const BONUS_TYPE_THRESHOLD = 3;

export const scoreArmy = (army: Card[]): number => {
  const monsters = army.map((card) => card.monster);
  if (!monsters.includes(SPHINX)) return NO_SPHINX_SCORE;

  const distinctTypeCount = new Set(monsters).size;
  if (distinctTypeCount <= BONUS_TYPE_THRESHOLD) return BASE_SPHINX_SCORE;

  const typesBeyondThree = distinctTypeCount - BONUS_TYPE_THRESHOLD;
  return BASE_SPHINX_SCORE + 2 * (typesBeyondThree - 1) + 1;
};

