export const scoreArmy = (army: Card[]): number => {
  const types = distinctMonsterTypes(army);
  if (!types.has(SPHINX)) return 0;

  const sphinxCount = army.filter((card) => card.monster === SPHINX).length;
  const scorePerSphinx =
    types.size <= MAX_TYPES_FOR_BASE_SCORE
      ? BASE_SPHINX_SCORE
      : scoreForManyTypes(types.size);

  return scorePerSphinx * sphinxCount;
};

